// debug context:start
console.log('context:', context);
console.log('context keys:', Object.keys(context));
console.log('context.data:', context.data);
console.log('context.panel:', context.panel);
console.log('panel keys:', JSON.stringify(Object.keys(context.panel ?? {})));
// debug context: end

// debug time range: start
const timeRange = context.panel.data.timeRange;
const timeRangeFrom = timeRange?.from?.valueOf();
const timeRangeTo = timeRange?.to?.valueOf();
console.log('timeRange:', timeRangeFrom, timeRangeTo);
// debug time range: end


const frame = context.panel.data.series[0];
if (!frame || !frame.fields.length) {
  return { title: { text: '데이터 없음', left: 'center', top: 'center' } };
}

const getField = (name) => frame.fields.find(f => f.name === name);

const traceIdField = getField('traceID');
const startTimeField = getField('startTime');
const serviceField = getField('traceService');
const nameField = getField('traceName');
const nestedField = getField('nested');

const points = (startTimeField?.values ?? []).map((t, i) => {
  const traceId = traceIdField?.values[i] ?? '';
  const service = serviceField?.values[i] ?? '';
  const name = nameField?.values[i] ?? traceId;

  // nested 프레임에서 duration, status 추출                                                                                                                                                              
  const nestedFrame = nestedField?.values[i]?.[0];
  const nestedFields = nestedFrame?.fields ?? [];
  const getNestedField = (n) => nestedFields.find(f => f.name === n)?.values[0];

  const duration = getNestedField('duration') ?? 0;
  const status = getNestedField('status') ?? 'unset';

  return {
    value: [t, duration / 1000000],
    traceId, name, service, status,
    itemStyle: {
      color: status === 'error' ? '#F44336'
        : status === 'ok' ? '#4CAF50'
          : '#4FC3F7',
      opacity: 0.85,
    },
  };
});


// 클릭 이벤트 등록                                                                                                                                                                                       
const chart = context.panel.chart;
if (chart) {
  chart.off('click');
  chart.on('click', (params) => {
    const traceId = params.data?.traceId;
    if (!traceId) return;

    // 클릭한 trace 시간 기준 ±30분                                                                                                                                                                         
    const startTime = params.data?.value[0]; // ms timestamp
    const from = startTime - 30 * 60 * 1000;
    const to = startTime + 30 * 60 * 1000;

    const query = JSON.stringify({
      datasource: 'tempo',
      queries: [{ query: traceId, queryType: 'traceql' }],
      range: { from: String(from), to: String(to) },
    });
    window.open(`/explore?orgId=1&left=${encodeURIComponent(query)}`, '_blank');
  });
}


// 기존 click 이벤트 아래에 추가
chart.off('brushSelected');
chart.on('brushSelected', (params) => {
  const selected = params.batch?.[0]?.selected ?? [];
  const traceIds = [];

  selected.forEach((s) => {
    s.dataIndex.forEach((idx) => {
      const seriesData = chart.getOption().series[s.seriesIndex]?.data;
      const traceId = seriesData?.[idx]?.traceId;
      if (traceId) traceIds.push(traceId);
    });
  });

  if (traceIds.length === 0) return;

  // 선택된 traceId들을 | 로 묶어 TraceQL 쿼리 생성
  const traceQL = traceIds.map(id => `{ traceId="${id}" }`).join(' || ');
  const query = JSON.stringify({
    datasource: 'tempo',
    queries: [{ query: traceQL, queryType: 'traceql' }],
    range: { from: 'now-1h', to: 'now' },
  });

  // 각 traceId를 별도 쿼리로 (최대 5개)
  const queries = traceIds.slice(0, 5).map((id, i) => ({
    refId: String.fromCharCode(65 + i),  // A, B, C...
    query: id,                            // trace ID 직접 전달
    queryType: 'traceql',
  }));

  const left = JSON.stringify({
    datasource: 'tempo',
    queries,
    range: { from: 'now-1h', to: 'now' },
  });

  // context.grafana.locationService.push(
  //   `/explore?orgId=1&left=${encodeURIComponent(query)}`, '_blank'
  // );
  window.open(`/explore?orgId=1&left=${encodeURIComponent(left)}`, '_blank');
});


return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const d = p.data;
      return [
        `<b>${d.name}</b>`,
        `Service: ${d.service}`,
        `Time: ${new Date(d.value[0]).toLocaleTimeString()}`,
        `Duration: ${d.value[1]} mssss`,
        `Status: ${d.status}`,
        `TraceID: ${d.traceId.substring(0, 16)}...`,
        `<a href="http://google.com">Trace 확인</a>`
      ].join('<br/>');
    },
  },
  toolbox: {
    feature: {
      brush: {
        type: ['rect', 'clear'],   // 사각형 드래그, 선택 해제
        title: { rect: '드래그 선택', clear: '선택 해제' },
      },
    },
    right: 10,
    top: 30,
  },
  brush: {
    toolbox: ['rect', 'clear'],
    xAxisIndex: 0,
    throttleType: 'debounce',
    throttleDelay: 300,
    outOfBrush: { colorAlpha: 0.2 },  // 선택 안 된 포인트 흐리게
  },
  xAxis: { type: 'time', name: 'Time', nameLocation: 'end', min: timeRangeFrom, max: timeRangeTo },
  yAxis: { type: 'value', name: 'Duration (ms)', nameLocation: 'end', min: 10 },
  legend: { data: ['ok', 'error', 'unset'], right: 10 },
  series: [
    {
      name: 'ok',
      type: 'scatter',
      data: points.filter(p => p.status === 'ok'),
      symbolSize: 8,
      itemStyle: { color: '#4CAF50' },
    },
    {
      name: 'error',
      type: 'scatter',
      data: points.filter(p => p.status === 'error'),
      symbolSize: 10,
      itemStyle: { color: '#F44336' },
    },
    {
      name: 'unset',
      type: 'scatter',
      data: points.filter(p => p.status === 'unset'),
      symbolSize: 8,
      itemStyle: { color: '#4FC3F7' },
    },
  ],
};

